// --- CONFIGURAÇÃO MESTRE: PRIME DENTE — MULTI-UNIDADE ---
const body = $input.item.json.body || $input.item.json;

const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || '';
const telefoneRaw = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';
const insistiu = body.insistiu === true || String(body.insistiu).toLowerCase() === 'true';

// ✅ CORREÇÃO: lê 'unidade_selecionada' OU 'unidade'
const unidade = (body.unidade_selecionada || body.unidade || 'meier').toLowerCase().trim();

const TIMEZONE = 'America/Sao_Paulo';

// ── Profissionais — Méier ─────────────────────────────────────
const LORRAINE_MEIER = { id: '6600846999945216', nome: 'Dra. Lorraine Ribeiro Mendes' };
const THIAGO_MEIER   = { id: '4826463870648320', nome: 'Dr. Thiago H. Q. Menezes' };

const PROF_MEIER = {
  1: THIAGO_MEIER,    // Segunda
  2: LORRAINE_MEIER,  // Terça
  3: LORRAINE_MEIER,  // Quarta
  4: THIAGO_MEIER,    // Quinta
  5: LORRAINE_MEIER,  // Sexta
  6: null,            // Sábado — fechado
  7: null             // Domingo — fechado
};

// ── Profissionais — Botafogo ──────────────────────────────────
const LORRAINE_BOTAFOGO = { id: '6073971665403904', nome: 'Dra. Lorraine Ribeiro Mendes' };
const THIAGO_BOTAFOGO   = { id: '6085639640186880', nome: 'Dr. Thiago H. Q. Menezes' };

const PROF_BOTAFOGO = {
  1: LORRAINE_BOTAFOGO,  // Segunda
  2: THIAGO_BOTAFOGO,    // Terça
  3: null,               // Quarta — sem atendimento
  4: LORRAINE_BOTAFOGO,  // Quinta
  5: THIAGO_BOTAFOGO,    // Sexta
  6: null,               // Sábado — fechado
  7: null                // Domingo — fechado
};

const FERIADOS = [
  '2026-04-21', // Tiradentes
  '2026-05-01', // Dia do Trabalho
  '2026-06-04', // Corpus Christi
  '2026-09-07', // Independência
  '2026-10-12', // N. Sra. Aparecida
  '2026-11-02', // Finados
  '2026-11-15', // Proclamação da República
  '2026-12-25', // Natal
  '2026-01-01', // Ano Novo
];

// ── Configs por unidade ───────────────────────────────────────
const CONFIG_MEIER = {
  subscriber_id:            '10114924740',
  business_id:              '5516186830241792',
  nome_unidade:             'Méier',
  nome_empresa:             'Prime Dente',
  link_agenda:              '57162',
  duracao_servico:          30,
  capacidade_simultanea:    1,
  timezone:                 TIMEZONE,
  limite_dias_busca_normal: 7,
  profissionais_por_dia:    PROF_MEIER,
  authorization:            'Basic ' + Buffer.from('primedente:ecdd291e-97ae-4f26-8d3b-d025c58a7985').toString('base64'),
  feriados:                 FERIADOS
};

const CONFIG_BOTAFOGO = {
  subscriber_id:            '48543547000160',
  business_id:              '6607905423622144',
  nome_unidade:             'Botafogo',
  nome_empresa:             'Prime Dente',
  link_agenda:              '73549',
  duracao_servico:          30,
  capacidade_simultanea:    1,
  timezone:                 TIMEZONE,
  limite_dias_busca_normal: 7,
  profissionais_por_dia:    PROF_BOTAFOGO,
  authorization:            'Basic ' + Buffer.from('primebotafogo:d7df9d4a-e641-4448-97bb-14b11595ddbc').toString('base64'),
  feriados:                 FERIADOS
};

const CONFIG = unidade === 'botafogo' ? CONFIG_BOTAFOGO : CONFIG_MEIER;

// ── Parse de datas ────────────────────────────────────────────
const hoje = DateTime.now().setZone(TIMEZONE);

const dataRaw = body.data_iso || body.data_inicio || body.data_agendada || '';
let dtP = null;

if (dataRaw) {
  dtP = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
}

const horaDoISO = (dtP && dtP.isValid && (dtP.hour > 0 || dtP.minute > 0))
  ? dtP.toFormat('HH:mm') : '';

const horaRaw = (body.horario_agendado && body.horario_agendado.length >= 4)
  ? body.horario_agendado
  : (body.horario && body.horario.length >= 4)
  ? body.horario
  : horaDoISO;

const horaFinal = horaRaw ? horaRaw.substring(0, 5) : '';

const dataFinal = (dtP && dtP.isValid) ? dtP.toFormat('yyyy-MM-dd') : '';

// ── Cálculo de data_inicio e data_fim ─────────────────────────
let dataMinimaRaw = body.data_minima || null;
let dtMinima = null;

if (dataMinimaRaw) {
  dtMinima = DateTime.fromISO(dataMinimaRaw, { zone: TIMEZONE });
  if (!dtMinima.isValid) dtMinima = DateTime.fromFormat(dataMinimaRaw, 'yyyy-MM-dd', { zone: TIMEZONE });
}

let dataInicioCalc = hoje;
if (dtMinima && dtMinima.isValid && dtMinima > dataInicioCalc) {
  dataInicioCalc = dtMinima;
} else if (dtP && dtP.isValid && dtP.startOf('day') > hoje.startOf('day')) {
  dataInicioCalc = dtP.startOf('day');
}

const dataInicio = dataInicioCalc.toFormat('yyyy-MM-dd');
const dataFim = dataFinal
  ? DateTime.fromISO(dataFinal, { zone: TIMEZONE }).plus({ days: 7 }).toFormat('yyyy-MM-dd')
  : hoje.plus({ days: 7 }).toFormat('yyyy-MM-dd');

// ── Profissional do dia solicitado (para debug) ───────────────
const dtParaProf = (dtP && dtP.isValid) ? dtP : hoje;
const profDoDia  = CONFIG.profissionais_por_dia[dtParaProf.weekday] || null;

return {
  json: {
    acao_fluxo:           body.action || body.acao_fluxo,
    id_atendimento:       idAtendimento,
    helena_company_id:    'ad711b94-9b7c-43d6-928f-208cda372a24',
    nome_paciente:        nomePaciente,
    telefone_limpo:       telefoneLimpo,
    insistiu:             insistiu,
    data_nascimento:      body.data_nascimento || '',
    data_inicio:          dataInicio,
    data_agendada:        dataFinal,
    data_antiga:          body.data_antiga || body['data-antiga'] || '',
    data_fim:             dataFim,
    horario_agendado:     horaFinal,
    horario_preferido:    body.horario_preferido || null,
    data_minima:          dataInicio,
    spin:                 body.SPIN || body.spin || null,
    profissional_do_dia:  profDoDia,
    config_agenda:        CONFIG
  }
};

// ── Validar Slot Agendar — Prime Dente v2.1 (com bloqueio de feriados) ──
let d = {};
try { d = $('Configuracao Unidades').first().json; } catch(e) { d = $input.item.json; }

const TIMEZONE      = d.config_agenda?.timezone || 'America/Sao_Paulo';
const PROF_POR_DIA  = d.config_agenda?.profissionais_por_dia || {};
const feriados      = new Set(d.config_agenda?.feriados || []);

// ── Bloqueio de feriado ───────────────────────────────────────
if (feriados.has(d.data_agendada)) {
  return {
    json: {
      ...d,
      validacao:               { aprovado: false, motivo: 'A clínica não atende neste dia (feriado).' },
      id_profissional_final:   null,
      nome_profissional_final: '',
      hora_buscada:            '',
      slots_encontrados_total: 0
    }
  };
}

// Resolve profissional pelo dia da data agendada
const dtAlvo    = DateTime.fromISO(d.data_agendada, { zone: TIMEZONE });
const profDoDia = PROF_POR_DIA[dtAlvo.weekday] || null;

const PROF_ID   = profDoDia ? String(profDoDia.id) : '';
const PROF_NOME = profDoDia ? profDoDia.nome : 'Profissional';

const inputItems    = $input.all().map(i => i.json);
const isNovoFormato = inputItems.length > 0 && Array.isArray(inputItems[0].AvaliableTimes);

let slots = [];
if (isNovoFormato) {
  slots = (inputItems[0].AvaliableTimes || []).filter(s => s.isSelectable !== false);
} else {
  slots = inputItems;
}

const norm = h => {
  if (!h) return '';
  const p = h.toString().split(':');
  return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'00');
};

const hAlvo = norm(d.horario_agendado || '');
const slotsNoHorario = slots.filter(s => norm(isNovoFormato ? s.from : s.From) === hAlvo);
const slotEscolhido  = slotsNoHorario.find(s =>
  String(isNovoFormato ? s.professionalId : s.ProfessionalId) === PROF_ID
);

let v = { aprovado: false, motivo: 'Horário indisponível.' };
let idF = null, nomeF = '';

if (!profDoDia) {
  v.motivo = 'A clínica não atende neste dia da semana.';
} else if (!slots.length) {
  v.motivo = 'Não há agenda aberta ou horários disponíveis neste dia.';
} else if (!hAlvo) {
  v.motivo = 'Horário solicitado não informado.';
} else if (slotEscolhido) {
  v = { aprovado: true, motivo: 'Horário disponível.' };
  idF = PROF_ID; nomeF = PROF_NOME;
} else {
  v.motivo = `O horário ${d.horario_agendado} não está disponível com ${PROF_NOME}.`;
}

return {
  json: {
    ...d,
    validacao:               v,
    id_profissional_final:   idF,
    nome_profissional_final: nomeF,
    hora_buscada:            hAlvo,
    slots_encontrados_total: slots.length
  }
};

