// ── Recuperar Reagendamento — Nucleodente ──────────────────────
const base = $('Validar Slot Remarcar').first().json;
const dur  = base.config_agenda?.duracao_servico || 30;

// ISO da nova data+hora com fuso Brasil
const dataISO = DateTime.fromFormat(
  base.data_agendada + ' ' + base.horario_agendado,
  'yyyy-MM-dd HH:mm',
  { zone: 'America/Sao_Paulo' }
).toISO();

// toTime pré-calculado
const toTime = DateTime.fromFormat(base.horario_agendado, 'HH:mm')
  .plus({ minutes: dur })
  .toFormat('HH:mm');

return {
  json: {
    ...base,
    id_paciente_final: base.patient_id_remarcar,  // já vem do Validar Slot Remarcar
    data_agendada_iso: dataISO,
    toTime_calculado:  toTime
  }
};

let idFinal = null;
let telefoneFinal = null;

// 1. Tenta pegar ID do paciente recém-criado
try {
  const novo = $('Criar Novo Paciente').all();
  if (novo.length > 0) {
    idFinal = novo[0].json.id || novo[0].json.PatientId || novo[0].json.personId || null;
  }
} catch(e) {}

// 2. Fallback: paciente já existente
if (!idFinal) {
  try {
    const exist = $('Buscar Paciente Agendar').all();
    if (exist.length > 0) {
      idFinal       = exist[0].json.id || exist[0].json.PatientId || exist[0].json.personId || null;
      telefoneFinal = exist[0].json.MobilePhone || exist[0].json.Phone || null;
    }
  } catch(e) {}
}

const base = $('Validar Slot Agendar').first().json;

if (!telefoneFinal) telefoneFinal = base.telefone_limpo;
telefoneFinal = telefoneFinal.toString().replace(/\D/g, '');

const dur = base.config_agenda?.duracao_servico || 30;
const toTime = DateTime.fromFormat(base.horario_agendado, 'HH:mm')
  .plus({ minutes: dur })
  .toFormat('HH:mm');

const spin = $('Configuracao Unidades').first().json.spin;
const notes = (spin ? spin + ' | ' : '') + 'Agendamento realizado via IA (Prime Dente)';

// ✅ Body montado aqui para evitar JSON inválido no HTTP node
const bodyAgendamento = {
  Clinic_BusinessId:    base.config_agenda.business_id,
  Patient_PersonId:     idFinal,
  Dentist_PersonId:     base.id_profissional_final,
  PatientName:          base.nome_paciente,
  MobilePhone:          telefoneFinal,
  date:                 base.data_agendada,
  fromTime:             base.horario_agendado,
  toTime:               toTime,
  Notes:                notes,
  CategoryColor:        '#FFD700',
  CategoryDescription:  'Avaliação'
};

return {
  json: {
    ...base,
    id_paciente_final:   idFinal,
    telefone_prontuario: telefoneFinal,
    to_time:             toTime,
    body_agendamento:    bodyAgendamento  // ✅ body pronto
  }
};

const cfg = $('CRM Config (Agendar)').first().json;
const cu = $('Configuracao Unidades').first().json;
const contactId = $('Buscar Sessao (Agendar)').first().json.contactId;
const resp = $('Buscar Card (Agendar)').first().json;
const arr = Array.isArray(resp) ? resp : (resp.items ?? resp.data ?? []);
const card = (arr && arr.length) ? arr[0] : null;
const existTags = card && Array.isArray(card.tagIds) ? card.tagIds : [];
const tagIds = Array.from(new Set([...existTags, cfg.ia_card_tag_id].filter(Boolean)));
const title = (card && card.title) || cu.nome_paciente || 'Paciente';

// --- Campos personalizados (DATETIME): agendado em = agora; agendado para = data/hora da consulta ---
const zone = 'America/Sao_Paulo';
const agoraISO = DateTime.now().setZone(zone).toISO();
const dtAg = DateTime.fromFormat(`${cu.data_agendada} ${cu.horario_agendado}`, 'yyyy-MM-dd HH:mm', { zone });
const paraISO = dtAg.isValid ? dtAg.toISO() : null;
const cf = {};
if (cfg.agendado_em_field_key) cf[cfg.agendado_em_field_key] = [agoraISO];
if (cfg.agendado_para_field_key && paraISO) cf[cfg.agendado_para_field_key] = [paraISO];
const temCF = Object.keys(cf).length > 0;

const moveBody = { fields: temCF ? ['stepId','tagIds','customFields'] : ['stepId','tagIds'], stepId: cfg.agendado_step_id, tagIds };
if (temCF) moveBody.customFields = cf;

const createBody = { stepId: cfg.agendado_step_id, title, contactIds: [contactId], tagIds: cfg.ia_card_tag_id ? [cfg.ia_card_tag_id] : [] };
if (temCF) createBody.customFields = cf;

return [{ json: { hasCard: !!card, cardId: card ? card.id : null, moveBodyJson: JSON.stringify(moveBody), createBodyJson: JSON.stringify(createBody) } }];

const cfg = $('CRM Config (Remarcar)').first().json;
const cu = $('Configuracao Unidades').first().json;
const contactId = $('Buscar Sessao (Remarcar)').first().json.contactId;
const resp = $('Buscar Card (Remarcar)').first().json;
const arr = Array.isArray(resp) ? resp : (resp.items ?? resp.data ?? []);
const card = (arr && arr.length) ? arr[0] : null;
const existTags = card && Array.isArray(card.tagIds) ? card.tagIds : [];
const tagIds = Array.from(new Set([...existTags, cfg.ia_card_tag_id].filter(Boolean)));
const title = (card && card.title) || cu.nome_paciente || 'Paciente';

// --- Campos personalizados (DATETIME): agendado em = agora; agendado para = data/hora da consulta ---
const zone = 'America/Sao_Paulo';
const agoraISO = DateTime.now().setZone(zone).toISO();
const dtAg = DateTime.fromFormat(`${cu.data_agendada} ${cu.horario_agendado}`, 'yyyy-MM-dd HH:mm', { zone });
const paraISO = dtAg.isValid ? dtAg.toISO() : null;
const cf = {};
if (cfg.agendado_em_field_key) cf[cfg.agendado_em_field_key] = [agoraISO];
if (cfg.agendado_para_field_key && paraISO) cf[cfg.agendado_para_field_key] = [paraISO];
const temCF = Object.keys(cf).length > 0;

const moveBody = { fields: temCF ? ['stepId','tagIds','customFields'] : ['stepId','tagIds'], stepId: cfg.agendado_step_id, tagIds };
if (temCF) moveBody.customFields = cf;

