// =============================================================
// LÓGICA INTELIGENTE — Prime Dente v4.2 (debug + parse robusto)
// Mudanças vs v4.1: parseDiaSeguro, diagnóstico por dia, output debug.
// A árvore de decisão A/B/C/D permanece INALTERADA.
// =============================================================

// ── 1. CONFIGURAÇÃO ───────────────────────────────────────────
const cfgNode = $('Configuracao Unidades').first().json;
const ca = cfgNode.config_agenda || {};

const TIMEZONE    = ca.timezone || 'America/Sao_Paulo';
const DUR_MIN     = ca.duracao_servico || 10;
const LIMITE_DIAS = ca.limite_dias_busca_normal || 7;
const GAP_MIN     = 180;

const PROF_POR_DIA = ca.profissionais_por_dia || {};

// ✅ FIX 2 — parse de data resiliente (ISO, yyyy-MM-dd, dd/MM/yyyy)
function parseDiaSeguro(jsonDate) {
  if (!jsonDate) return null;
  let dt = DateTime.fromISO(jsonDate, { zone: TIMEZONE });
  if (!dt.isValid) dt = DateTime.fromFormat(String(jsonDate).slice(0, 10), 'yyyy-MM-dd', { zone: TIMEZONE });
  if (!dt.isValid) dt = DateTime.fromFormat(jsonDate, 'dd/MM/yyyy', { zone: TIMEZONE });
  return dt.isValid ? dt : null;
}

// ── 2. INPUT ──────────────────────────────────────────────────
const diasAPI = $input.all().map(i => i.json);

// ── 3. DADOS DO PEDIDO ────────────────────────────────────────
const insistiu = cfgNode.insistiu === true;

const hPreferidoRaw = cfgNode.horario_preferido;
const hPreferido = (hPreferidoRaw && hPreferidoRaw !== 'null' && hPreferidoRaw !== 'undefined')
  ? hPreferidoRaw : null;

const hRaw  = cfgNode.horario_agendado || hPreferido || '';
const dRaw  = cfgNode.data_agendada || '';
const agora = DateTime.now().setZone(TIMEZONE);

let dtSolicitado = null;
if (dRaw && hRaw) {
  dtSolicitado = DateTime.fromFormat(`${dRaw} ${hRaw}`, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
}

let diffDias = 0, bloqueado = false;
if (dtSolicitado?.isValid) {
  diffDias = dtSolicitado.startOf('day').diff(agora.startOf('day'), 'days').days;
  if (diffDias > LIMITE_DIAS && !insistiu) bloqueado = true;
}

// ── 4. HELPERS ────────────────────────────────────────────────
function horaParaMin(str) {
  if (!str) return -1;
  const p = str.split(':');
  return parseInt(p[0]) * 60 + parseInt(p[1] || '0');
}

function blocoParaAbsMin(b) {
  const [yyyy, mm, dd] = b.data.split('-');
  const diasMs = new Date(parseInt(yyyy), parseInt(mm) - 1, parseInt(dd)).getTime();
  return Math.floor(diasMs / 60000) + b.minutos;
}

function sugerirComGap(blocos, n = 3, gapMin = GAP_MIN) {
  const resultado = [];
  let ultimoAbsMin = -Infinity;
  for (const b of blocos) {
    const absMin = blocoParaAbsMin(b);
    if (absMin - ultimoAbsMin >= gapMin) {
      resultado.push(b);
      ultimoAbsMin = absMin;
      if (resultado.length >= n) break;
    }
  }
  return resultado;
}

function sugerirComGapAncorado(blocos, minAncora, n = 3, gapMin = GAP_MIN) {
  const ordenados = [...blocos].sort((a, b) =>
    Math.abs(a.minutos - minAncora) - Math.abs(b.minutos - minAncora)
  );
  const resultado = [];
  for (const b of ordenados) {
    const respeitaGap = resultado.every(r =>
      Math.abs(blocoParaAbsMin(r) - blocoParaAbsMin(b)) >= gapMin
    );
    if (respeitaGap) {
      resultado.push(b);
      if (resultado.length >= n) break;
    }
  }
  return resultado.sort((a, b) => a.minutos - b.minutos);
}

function sugerirPorPreferido(blocos, hPref, n = 3) {
  const minPref = horaParaMin(hPref);
  const porDia = {};
  for (const b of blocos) {
    if (!porDia[b.data]) {
      porDia[b.data] = b;
    } else {
      if (Math.abs(b.minutos - minPref) < Math.abs(porDia[b.data].minutos - minPref))
        porDia[b.data] = b;
    }
  }
  return Object.keys(porDia).sort().slice(0, n).map(d => porDia[d]);
}

// ── 5. PROCESSAR UM DIA (com diagnóstico) ─────────────────────
// ✅ FIX 3 — retorna { blocos, diag } para expor por que um dia esvaziou
function processarDia(dia) {
  const dtDia = parseDiaSeguro(dia.jsonDate);
  const diag = {
    data:                  dia.jsonDate || null,
    data_parseou:          !!dtDia,
    weekday:               dtDia ? dtDia.weekday : null,
    slots_brutos:          (dia.AvaliableTimes || []).length,
    slots_selecionaveis:   0,
    slots_do_profissional: 0,
    prof_esperado_id:      null,
    prof_esperado_nome:    null,
    motivo_descartado:     null
  };

  if (!dtDia) {
    diag.motivo_descartado = 'data_nao_parseou';
    return { blocos: [], diag };
  }

  const profDoDia = PROF_POR_DIA[dtDia.weekday] || null;
  if (!profDoDia) {
    diag.motivo_descartado = 'sem_profissional_no_dia';
    return { blocos: [], diag };
  }

  const profId   = String(profDoDia.id);
  const profNome = profDoDia.nome;
  diag.prof_esperado_id   = profId;
  diag.prof_esperado_nome = profNome;

  const selecionaveis = (dia.AvaliableTimes || []).filter(s => s.isSelectable !== false);
  diag.slots_selecionaveis = selecionaveis.length;

  const blocos = [];
  for (const slot of selecionaveis) {
    if (String(slot.professionalId) !== profId) continue;
    blocos.push({
      data:        dia.jsonDate,
      semana:      dia.Week,
      minutos:     horaParaMin(slot.from),
      horario:     slot.from,
      horario_fim: slot.to,
      profId,
      profNome
    });
  }
  diag.slots_do_profissional = blocos.length;

  // Classifica o motivo de o dia ter esvaziado (só para debug)
  if (diag.slots_brutos === 0) {
    diag.motivo_descartado = 'dia_sem_slots_na_api';
  } else if (selecionaveis.length === 0) {
    diag.motivo_descartado = 'todos_slots_nao_selecionaveis';
  } else if (blocos.length === 0) {
    diag.motivo_descartado = 'todos_slots_de_outro_profissional';
  }

  return { blocos: blocos.sort((a, b) => a.minutos - b.minutos), diag };
}

// ── 6. TODOS OS BLOCOS ────────────────────────────────────────
// ✅ FIX 1 — coleta diagnóstico por dia
let todosBlocos = [];
const diagPorDia = [];
for (const dia of diasAPI) {
  const r = processarDia(dia);
  todosBlocos = todosBlocos.concat(r.blocos);
  diagPorDia.push(r.diag);
}

// ── FILTRO FERIADOS ───────────────────────────────────────────
const feriados = new Set(ca.feriados || []);
todosBlocos = todosBlocos.filter(b => !feriados.has(b.data));

function blocosFuturoAPartirDe(dataAlvo) {
  if (!dataAlvo) return todosBlocos;
  const futuros = todosBlocos.filter(b => b.data >= dataAlvo);
  return futuros.length > 0 ? futuros : todosBlocos;
}

// ── 7. FORMATAÇÃO ─────────────────────────────────────────────
const fmtBloco = b => {
  const [yyyy, mm, dd] = b.data.split('-');
  return `🗓️ *${dd}/${mm} (${b.semana})* às *${b.horario}* – *${b.horario_fim}* com *${b.profNome}*`;
};

const dtLabel = dtSolicitado?.isValid
  ? dtSolicitado.setLocale('pt-BR').toFormat('dd/MM (cccc)')
  : (dRaw || 'data solicitada');

const prefLabel = hPreferido
  ? `\n\n💡 _Priorizei horários próximos à sua preferência: *${hPreferido}*_`
  : '';

// ── 8. DECISÃO PRINCIPAL ──────────────────────────────────────
let resultado, exactMatch = false;
const sugestoesHorarios = [];
let blocosSugeridos = [];

// CAMINHO A — Data distante + NÃO insistiu
if (bloqueado) {
  blocosSugeridos = hPreferido
    ? sugerirPorPreferido(todosBlocos, hPreferido, 3)
    : sugerirComGap(todosBlocos, 3);
  if (blocosSugeridos.length === 0) {
    resultado = `😕 Não há horários disponíveis no momento. Posso verificar outra data?`;
  } else {
    blocosSugeridos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `⚠️ A data que você pediu (*${dtLabel}*) está a *${Math.ceil(diffDias)} dias* de hoje.\n\n` +
      `Para garantir um atendimento mais rápido, separei os primeiros horários disponíveis:${prefLabel}\n\n` +
      blocosSugeridos.map(fmtBloco).join('\n');
  }
}
// CAMINHO B — Data distante + insistiu
else if (diffDias > LIMITE_DIAS && insistiu) {
  const dataAlvo      = dtSolicitado.toFormat('yyyy-MM-dd');
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;
  const blocosDoDia   = todosBlocos.filter(b => b.data === dataAlvo);
  const blocoExato    = minSolicitado >= 0 ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

  if (blocoExato) {
    exactMatch = true;
    blocosSugeridos = [blocoExato];
    sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
    resultado = `✅ Consegui o horário que você pediu!\n\n${fmtBloco(blocoExato)}\n\nConfirmo o agendamento?`;
  } else if (blocosDoDia.length === 0) {
    const ehFeriado = feriados.has(dataAlvo);
    const futuros = blocosFuturoAPartirDe(dataAlvo);
    blocosSugeridos = hPreferido
      ? sugerirPorPreferido(futuros, hPreferido, 3)
      : sugerirComGap(futuros, 3);
    blocosSugeridos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    const motivoIndisponivel = ehFeriado
      ? `😕 O dia *${dtLabel}* é feriado e a clínica não atende.`
      : `😕 Não há horários disponíveis em *${dtLabel}*.`;
    resultado =
      `${motivoIndisponivel}\n\nSeparei os primeiros horários disponíveis a partir dessa data:${prefLabel}\n\n` +
      blocosSugeridos.map(fmtBloco).join('\n') + `\n\nQual prefere? Ou verifico outro dia?`;
  } else {
    blocosSugeridos = minSolicitado >= 0
      ? sugerirComGapAncorado(blocosDoDia, minSolicitado, 3)
      : sugerirComGap(blocosDoDia, 3);
    blocosSugeridos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `O horário das *${hRaw}* não está disponível em *${dtLabel}*, mas encontrei estas opções neste mesmo dia:${prefLabel}\n\n` +
      blocosSugeridos.map(fmtBloco).join('\n') + `\n\nQual prefere? Ou verifico outro dia?`;
  }
}
// CAMINHOS C / D — Data normal (≤ 7 dias)
else {
  const dataAlvo      = dtSolicitado?.isValid ? dtSolicitado.toFormat('yyyy-MM-dd') : null;
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;

  if (dataAlvo && feriados.has(dataAlvo)) {
    const futuros = blocosFuturoAPartirDe(dataAlvo);
    blocosSugeridos = hPreferido
      ? sugerirPorPreferido(futuros, hPreferido, 3)
      : sugerirComGap(futuros, 3);
    blocosSugeridos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    if (blocosSugeridos.length === 0) {
      resultado = `😕 O dia *${dtLabel}* é feriado e não há outros horários disponíveis no período. Posso verificar outra data?`;
    } else {
      resultado =
        `😕 O dia *${dtLabel}* é feriado e a clínica não atende.\n\nSeparei os próximos horários disponíveis:${prefLabel}\n\n` +
        blocosSugeridos.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
    }
  } else {
    const blocosDoDia = dataAlvo ? todosBlocos.filter(b => b.data === dataAlvo) : todosBlocos;
    const blocoExato  = (minSolicitado >= 0 && blocosDoDia.length > 0)
      ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

    if (blocoExato) {
      exactMatch = true;
      blocosSugeridos = [blocoExato];
      sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
      resultado =
        `✅ Ótima notícia! O horário *${dtLabel} às ${blocoExato.horario}* está disponível ` +
        `com *${blocoExato.profNome}*.\n\nPosso confirmar sua avaliação?`;
    } else if (blocosDoDia.length === 0) {
      const futuros = blocosFuturoAPartirDe(dataAlvo);
      blocosSugeridos = hPreferido
        ? sugerirPorPreferido(futuros, hPreferido, 3)
        : sugerirComGap(futuros, 3);
      if (blocosSugeridos.length === 0) {
        resultado = `😕 Não há horários disponíveis no período consultado. Posso verificar outras datas?`;
      } else {
        blocosSugeridos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
        resultado =
          `😕 Não há horários disponíveis em *${dtLabel}*.\n\nSeparei os primeiros horários disponíveis a partir dessa data:${prefLabel}\n\n` +
          blocosSugeridos.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
      }
    } else {
      blocosSugeridos = minSolicitado >= 0
        ? sugerirComGapAncorado(blocosDoDia, minSolicitado, 3)
        : sugerirComGap(blocosDoDia, 3);
      blocosSugeridos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
      const intro = minSolicitado >= 0
        ? `O horário das *${hRaw}* não está disponível para *${dtLabel}*, mas encontrei estas opções:`
        : `Encontrei os seguintes horários disponíveis para *${dtLabel}*:`;
      resultado = `📅 ${intro}${prefLabel}\n\n` + blocosSugeridos.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
    }
  }
}

// ── 9. OUTPUT ─────────────────────────────────────────────────
const profNomeFinal = blocosSugeridos.length > 0 ? blocosSugeridos[0].profNome : '';

return {
  json: {
    resultado,
    sugestoes_horarios:      sugestoesHorarios,
    profissional_nome:       profNomeFinal,
    data_distante_bloqueada: bloqueado,
    exact_match:             exactMatch,
    diff_dias:               Math.ceil(diffDias),
    total_dias_api:          diasAPI.length,
    total_blocos_validos:    todosBlocos.length,

    // ── DEBUG (fixes 1 e 3) — remover depois de diagnosticar ──
    debug_dias_api:       diasAPI.map(d => d.jsonDate || null),
    debug_blocos_por_dia: diagPorDia,
    debug_resumo:         diagPorDia.map(d =>
      `${d.data}: bruto=${d.slots_brutos} sel=${d.slots_selecionaveis} prof=${d.slots_do_profissional}` +
      (d.motivo_descartado ? ` [${d.motivo_descartado}]` : '')
    )
  }
};
